fn solve(a: i8, b: i8, s: Vec<char>) -> Vec<char> {
    // The string must have exactly (a + b + 1) characters.
    let expected_len = (a + b + 1) as usize;
    if s.len() != expected_len {
        return vec!['N', 'o'];
    }

    // The hyphen must be exactly at index `a` (0-based).
    let hyphen_idx = a as usize;
    if hyphen_idx >= s.len() {
        return vec!['N', 'o'];
    }

    // Check each character: at hyphen_idx it must be '-', elsewhere it must be a digit.
    for (i, &ch) in s.iter().enumerate() {
        if i == hyphen_idx {
            if ch != '-' {
                return vec!['N', 'o'];
            }
        } else {
            if !ch.is_ascii_digit() {
                return vec!['N', 'o'];
            }
        }
    }

    // If all checks pass, it's a valid postal code pattern.
    vec!['Y', 'e', 's']
}

